{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-J5XCCl/src/env.js","content":"/** The environment layer: one `CONF_...` line per setting, read from standard input. */

import { SETTINGS } from './schema.js'

/** One refusal of an environment line, carrying the 1-based line and column it was read at. */
export class EnvError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'EnvError'
    this.line = line
    this.column = column
  }
}

/** Every schema key's environment name, e.g. `server.port` under `CONF_SERVER_PORT`. */
const KEY_BY_NAME = new Map(SETTINGS.map(declared => [`CONF_${declared.key.toUpperCase().replace(/\./g, '_')}`, declared.key]))

/** The 1-based column of the first non-space character of `raw`. */
function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * The column of a value's first character, or, when the value is empty, one past the
 * raw line's last non-space character.
 * @param {string} raw - the untrimmed source line.
 * @param {string} trimmed - `raw.trim()`.
 * @param {number} split - the index, in `trimmed`, of the `=` that separates name from value.
 * @returns {number} the 1-based column.
 */
function valueColumn(raw, trimmed, split) {
  const rest = trimmed.slice(split + 1)
  if (rest.trim() === '') return raw.trimEnd().length + 1
  const leading = rest.length - rest.trimStart().length
  return indent(raw) + split + 1 + leading
}

/**
 * Parse the environment layer's text into its settings.
 * @param {string} text - the whole of standard input.
 * @returns {Map<string, {text: string, line: number, column: number}>} each schema key's raw
 *   value and the position of that value, in the order the input writes them.
 * @throws {EnvError} on the first line the grammar refuses.
 */
export function parseEnv(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  const seen = new Set()
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const split = trimmed.indexOf('=')
    if (split === -1) throw new EnvError(line, indent(raw), 'expected NAME=VALUE')
    const name = trimmed.slice(0, split).trim()
    if (name === '') throw new EnvError(line, indent(raw), 'expected a variable name')
    const key = KEY_BY_NAME.get(name)
    if (key === undefined) throw new EnvError(line, indent(raw), `unknown environment variable ${name}`)
    if (seen.has(name)) throw new EnvError(line, indent(raw), `${name} is set twice`)
    seen.add(name)
    const text = trimmed.slice(split + 1).trim()
    values.set(key, { text, line, column: valueColumn(raw, trimmed, split) })
  }
  return values
}
"}

