 * @returns {{key: string, type: string, members?: string[], default: string} | undefined} the setting.
 */
export function setting(key) {
  return BY_KEY.get(key)
}

const DURATION_UNIT_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce one setting's raw text by its declared type, and render it back to text.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting, as `setting` returns it.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the rendered value.
 * @throws {Error} `<key> is not ...: <text>` or `<key> has an empty item: <text>` when the text does not fit the type.
 */
export function coerce(declared, text) {
  const { key, type } = declared
  switch (type) {
    case 'string':
      return text
    case 'integer':
      if (!/^-?(0|[1-9]\d*)$/.test(text)) throw new Error(`${key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new Error(`${key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new Error(`${key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = /^(\d+)(ms|s|m|h)$/.exec(text)
      if (!match) throw new Error(`${key} is not a duration: ${text}`)
      return String(BigInt(match[1]) * DURATION_UNIT_MS[match[2]])
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new Error(`${key} has an empty item: ${text}`)
      const seen = new Set()
      const kept = []
      for (const item of items) {
        if (seen.has(item)) continue
        seen.add(item)
        kept.push(item)
      }
      return kept.join(',')
    }
    default:
      throw new Error(`unknown type ${type}`)
  }
}"}

