/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, values: Map<string, {text: string, line: number, column: number}>}[]} layers -
 *   the layers, weakest first.
 * @returns {Map<string, {text: string, line: number, column: number, layer: string}>} each key's winning value,
 *   its position, and the name of the layer that won it.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) merged.set(key, { ...entry, layer: layer.name })
  }
  return merged
}
"}

